def isBalanced(s: str) -> bool:
    count = 0
    for char in s:
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
        if count < 0:
            return False
    return count == 0

def main():
    test_strings = [
        "(())",
        "(()",
        "())()",
        "()(())"
    ]

    for s in test_strings:
        print("true" if isBalanced(s) else "false")

if __name__ == "__main__":
    main()

