from dataclasses import dataclass
from typing import Optional

@dataclass
class Node:
    value: int
    left: Optional['Node'] = None
    right: Optional['Node'] = None

def treeSum(node: Optional[Node]) -> int:
    if node is None:
        return 0
    return node.value + treeSum(node.left) + treeSum(node.right)

def main():
    # Create the tree:
    #         5
    #        / \
    #       3   8
    #      / \   \
    #     1   4   10
    tree = Node(5,
        left=Node(3,
            left=Node(1),
            right=Node(4)
        ),
        right=Node(8,
            right=Node(10)
        )
    )

    # Calculate and print the sum
    total_sum = treeSum(tree)
    print(total_sum)

if __name__ == "__main__":
    main()

