import std/io (println)
import std/fs (readFile, writeFile)
import std/json (encode, jo, kv, js, jnum, ja, decode, getString, getInt, getStringArrayStrict)
import std/string (chars)
import std/list (length)
import std/option (Option, Some, None)
import std/result (Result, Ok, Err)

type Config = {app_name: string, version: string, port: int, features: [string]}

pure func countChar(target: string, cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => (if c == target then 1 else 0) + countChar(target, rest)
  }

pure func countDots(s: string) -> int {
  let cs = chars(s);
  countChar(".", cs)
}

func parseConfig(content: string) -> Option[Config] =
  match decode(content) {
    Err(_) => None,
    Ok(obj) =>
      match getString(obj, "app_name") {
        None => None,
        Some(name) =>
          match getString(obj, "version") {
            None => None,
            Some(ver) =>
              match getInt(obj, "port") {
                None => None,
                Some(port) =>
                  match getStringArrayStrict(obj, "features") {
                    None => None,
                    Some(feats) =>
                      if port < 1024 || port > 65535 then None
                      else if countDots(ver) != 2 then None
                      else if length(feats) == 0 then None
                      else Some({app_name: name, version: ver, port: port, features: feats})
                  }
              }
          }
      }
  }

export func main() -> () ! {IO, FS} {
  let jsonStr = encode(jo([
    kv("app_name", js("MyApp")),
    kv("version", js("1.0.0")),
    kv("port", jnum(8080.0)),
    kv("features", ja([js("logging"), js("auth"), js("api")]))
  ]));
  let _ = writeFile("app_config.json", jsonStr);
  let content = readFile("app_config.json");
  match parseConfig(content) {
    Some(cfg) => {
      let msg = "Loaded " ++ cfg.app_name ++ " v" ++ cfg.version ++ " on port " ++ show(cfg.port) ++ " with " ++ show(length(cfg.features)) ++ " features";
      println(msg)
    },
    None => println("Invalid configuration")
  }
}

