import std/io (println)
import std/fs (writeFile, readFile)
import std/string (split, contains, stringToInt)
import std/json (encode, jo, kv, js, jnum, ja)
import std/math (intToFloat)
import std/list (map, length)
import std/option (Option, Some, None)

pure func dropHeader(xs: [string]) -> [string] =
  match xs {
    [] => [],
    _ :: rest => rest
  }

pure func parseLine(line: string) -> Option[{name: string, age: int, email: string}] =
  match split(line, ",") {
    name :: ageStr :: email :: [] =>
      match stringToInt(ageStr) {
        Some(age) =>
          if age > 0 && contains(email, "@")
          then Some({name: name, age: age, email: email})
          else None,
        None => None
      },
    _ => None
  }

pure func collectValid(lines: [string]) -> [{name: string, age: int, email: string}] =
  match lines {
    [] => [],
    l :: rest =>
      match parseLine(l) {
        Some(rec) => rec :: collectValid(rest),
        None => collectValid(rest)
      }
  }

pure func recordToJson(u: {name: string, age: int, email: string}) =
  jo([
    kv("name", js(u.name)),
    kv("age", jnum(intToFloat(u.age))),
    kv("email", js(u.email))
  ])

export func main() -> () ! {IO, FS} {
  let csv = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com";
  let _ = writeFile("users.csv", csv);
  let content = readFile("users.csv");
  let lines = split(content, "\n");
  let rows = dropHeader(lines);
  let valid = collectValid(rows);
  let jsonArray = ja(map(recordToJson, valid));
  let jsonStr = encode(jsonArray);
  let _ = writeFile("users.json", jsonStr);
  let count = length(valid);
  println("Converted " ++ show(count) ++ " valid rows to users.json")
}

