from typing import TypeVar, Generic, Callable
from dataclasses import dataclass

# Type markers for Pure and IO effects
T = TypeVar('T')

@dataclass
class Pure(Generic[T]):
    """Wrapper for pure computations"""
    value: T

    def run(self) -> T:
        return self.value

@dataclass
class IO(Generic[T]):
    """Wrapper for effectful computations"""
    effect: Callable[[], T]

    def run(self) -> T:
        return self.effect()

# PURE functions - return Pure[T]
def double(x: int) -> Pure[int]:
    """Pure function: doubles a number"""
    return Pure(x * 2)

def add(a: int, b: int) -> Pure[int]:
    """Pure function: adds two numbers"""
    return Pure(a + b)

# EFFECTFUL functions - return IO[T]
def printResult(label: str, value: int) -> IO[None]:
    """Effectful function: prints a labeled result"""
    def effect():
        print(f"{label}: {value}")
    return IO(effect)

def compute_and_print() -> IO[None]:
    """Effectful function: computes using pure functions and prints result"""
    def effect():
        # Call pure functions and extract their values
        result1 = double(5).run()
        result2 = add(result1, 3).run()
        # Call effectful function and run it
        printResult("Result", result2).run()
    return IO(effect)

if __name__ == "__main__":
    compute_and_print().run()

