from typing import Generic, TypeVar, Union

T = TypeVar('T')

class Ok(Generic[T]):
    def __init__(self, value: T):
        self.value = value

    def is_ok(self) -> bool:
        return True

    def is_err(self) -> bool:
        return False

class Err:
    def __init__(self, message: str):
        self.message = message

    def is_ok(self) -> bool:
        return False

    def is_err(self) -> bool:
        return True

Result = Union[Ok[T], Err]

def parse_int(s: str) -> Result:
    try:
        n = int(s)
        return Ok(n)
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)

def chain_parse_and_divide(s: str, divisor: int):
    result = parse_int(s)
    if result.is_err():
        return result

    value = result.value
    return divide_safe(value, divisor)

def print_result(result: Result):
    if result.is_ok():
        print(f"Result: {result.value}")
    else:
        print(f"Error: {result.message}")

if __name__ == "__main__":
    result1 = chain_parse_and_divide("10", 2)
    print_result(result1)

    result2 = chain_parse_and_divide("10", 0)
    print_result(result2)

    result3 = parse_int("abc")
    print_result(result3)

