from dataclasses import dataclass

@dataclass
class Num:
    value: int

@dataclass
class Add:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Mul:
    left: 'Expr'
    right: 'Expr'

Expr = Num | Add | Mul

def eval(expr: Expr) -> int:
    match expr:
        case Num(value):
            return value
        case Add(left, right):
            return eval(left) + eval(right)
        case Mul(left, right):
            return eval(left) * eval(right)

if __name__ == "__main__":
    expression = Mul(Add(Num(3), Num(4)), Add(Num(2), Num(5)))
    result = eval(expression)
    print(result)

