  match xs {
    [] => false,
    y :: rest => if x == y then true else contains(x, rest)
  }

pure func enqueue(x: int, queue: [int]) -> [int] =
  match queue {
    [] => [x],
    y :: rest => y :: enqueue(x, rest)
  }

pure func enqueueAll(xs: [int], queue: [int]) -> [int] =
  match xs {
    [] => queue,
    x :: rest => enqueueAll(rest, enqueue(x, queue))
  }

pure func getNeighbors(node: int, graph: Graph) -> [int] =
  match graph {
    [] => [],
    (n, neighbors) :: rest => if n == node then neighbors else getNeighbors(node, rest)
  }

pure func filterUnvisited(nodes: [int], visited: [int]) -> [int] =
  match nodes {
    [] => [],
    n :: rest => if contains(n, visited) then filterUnvisited(rest, visited) else n :: filterUnvisited(rest, visited)
  }

pure func bfsHelper(queue: [int], visited: [int], graph: Graph, result: [int]) -> [int] =
  match queue {
    [] => result,
    current :: restQueue => 
      if contains(current, visited) then bfsHelper(restQueue, visited, graph, result)
      else {
        let newVisited = current :: visited;
        let neighbors = getNeighbors(current, graph);
        let unvisitedNeighbors = filterUnvisited(neighbors, newVisited);
        let newQueue = enqueueAll(unvisitedNeighbors, restQueue);
        bfsHelper(newQueue, newVisited, graph, result ++ [current])
      }
  }

pure func bfs(start: int, graph: Graph) -> [int] =
  bfsHelper([start], [], graph, [])

func printList(xs: [int]) -> () ! {IO} =
  match xs {
    [] => (),
    x :: rest => {
      println(show(x));
      printList(rest)
    }
  }

export func main() -> () ! {IO} {
  let graph: Graph = [(1, [2, 3]), (2, [4]), (3, [4, 5]), (4, []), (5, [])];
  let visited = bfs(1, graph);
  printList(visited)
}

