from dataclasses import dataclass
from typing import Union

@dataclass
class TVar:
    name: str

    def __str__(self):
        return self.name

@dataclass
class TLam:
    var: str
    body: 'Term'

    def __str__(self):
        return f"(λ{self.var}. {self.body})"

@dataclass
class TApp:
    f: 'Term'
    arg: 'Term'

    def __str__(self):
        return f"({self.f} {self.arg})"

Term = Union[TVar, TLam, TApp]

def subst(term: Term, var: str, replacement: Term) -> Term:
    if isinstance(term, TVar):
        return replacement if term.name == var else term
    elif isinstance(term, TLam):
        if term.var == var:
            return term 
        return TLam(term.var, subst(term.body, var, replacement))
    elif isinstance(term, TApp):
        return TApp(subst(term.f, var, replacement), subst(term.arg, var, replacement))
    else:
        raise TypeError(f"Unknown term type: {type(term)}")

def eval_term(term: Term) -> Term:
    while True:
        if isinstance(term, TApp):
            f_val = eval_term(term.f)
            arg_val = eval_term(term.arg)
            if isinstance(f_val, TLam):
                term = subst(f_val.body, f_val.var, arg_val)
                continue
            return TApp(f_val, arg_val)
        return term

def main():
    # Represents: (λx. λy. x) 1 2
    expression = TApp(
        TApp(
            TLam("x", TLam("y", TVar("x"))),
            TVar("1")
        ),
        TVar("2")
    )

    result = eval_term(expression)
    print(result)

if __name__ == "__main__":
    main()

