pure func cmpString(a: string, b: string) -> int =
  if a < b then -1 else if a > b then 1 else 0

pure func containsUser(u: string, us: [string]) -> bool =
  match us {
    [] => false,
    x :: rest => if x == u then true else containsUser(u, rest)
  }

pure func allAlpha(cs: [string]) -> bool =
  match cs {
    [] => true,
    c :: rest => if c >= "a" && c <= "z" then allAlpha(rest) else false
  }

pure func isLowerAlpha(s: string) -> bool {
  let cs = chars(s);
  match cs {
    [] => false,
    _ => allAlpha(cs)
  }
}

pure func extractUser(msg: string) -> Option[string] {
  let parts = split(msg, ": ");
  match last(parts) {
    Some(seg) => if isLowerAlpha(seg) then Some(seg) else None,
    None => None
  }
}

pure func process(lines: [string], info: int, err: int, warn: int, users: [string]) -> {info: int, err: int, warn: int, users: [string]} =
  match lines {
    [] => {info: info, err: err, warn: warn, users: users},
    line :: rest => {
      let tokens = split(line, " ");
      let level = match nth(tokens, 2) { Some(lv) => lv, None => "" };
      let msgTokens = drop(3, tokens);
      let msg = join(" ", msgTokens);
      let info2 = if level == "INFO" then info + 1 else info;
      let err2 = if level == "ERROR" then err + 1 else err;
      let warn2 = if level == "WARNING" then warn + 1 else warn;
      let users2 = match extractUser(msg) {
        Some(u) => if containsUser(u, users) then users else u :: users,
        None => users
      };
      process(rest, info2, err2, warn2, users2)
    }
  }

export func main() -> () ! {IO, FS} {
  let lines = [
    "2024-10-29 10:00:00 INFO User logged in: alice",
    "2024-10-29 10:01:15 ERROR Database connection failed",
    "2024-10-29 10:02:30 INFO User logged in: bob",
    "2024-10-29 10:03:45 WARNING High memory usage: 85%",
    "2024-10-29 10:05:00 ERROR API timeout: /users endpoint",
    "2024-10-29 10:06:15 INFO User logged out: alice"
  ];
  let content = join("\n", lines);
  let _ = writeFile("app.log", content);
  let raw = readFile("app.log");
  let rawLines = split(raw, "\n");
  let cleanLines = filter(func(s: string) -> bool { s != "" }, rawLines);
  let stats = process(cleanLines, 0, 0, 0, []);
  let total = length(cleanLines);
  let infoPct = stats.info * 100 / total;
  let errPct = stats.err * 100 / total;
  let warnPct = stats.warn * 100 / total;
  let sortedUsers = sortBy(cmpString, stats.users);
  let usersStr = join(", ", sortedUsers);
  println("Total log entries: " ++ show(total));
  println("INFO: " ++ show(stats.info) ++ " (" ++ show(infoPct) ++ "%)");
  println("ERROR: " ++ show(stats.err) ++ " (" ++ show(errPct) ++ "%)");
  println("WARNING: " ++ show(stats.warn) ++ " (" ++ show(warnPct) ++ "%)");
  println("Unique users: " ++ usersStr)
}

