from dataclasses import dataclass
from typing import List, Tuple, Union

# 1. Define an AST
@dataclass
class Num:
    value: int

@dataclass
class Var:
    name: str

@dataclass
class Add:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Mul:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Let:
    var: str
    expr: 'Expr'
    body: 'Expr'

Expr = Union[Num, Var, Add, Mul, Let]
Value = int
Env = List[Tuple[str, Value]]

# 3. Implement lookup
def lookup(name: str, env: Env) -> Value:
    """Finds a variable's value in the environment."""
    for var_name, value in env:
        if var_name == name:
            return value
    raise NameError(f"Variable '{name}' not found in environment")

# 4. Implement eval
def eval_expr(expr: Expr, env: Env) -> Value:
    """Evaluates an expression in an environment."""
    if isinstance(expr, Num):
        return expr.value
    elif isinstance(expr, Var):
        return lookup(expr.name, env)
    elif isinstance(expr, Add):
        left_val = eval_expr(expr.left, env)
        right_val = eval_expr(expr.right, env)
        return left_val + right_val
    elif isinstance(expr, Mul):
        left_val = eval_expr(expr.left, env)
        right_val = eval_expr(expr.right, env)
        return left_val * right_val
    elif isinstance(expr, Let):
        val = eval_expr(expr.expr, env)
        new_env = [(expr.var, val)] + env
        return eval_expr(expr.body, new_env)
    else:
        raise TypeError(f"Unknown expression type: {type(expr)}")

def main():
    """Main function to evaluate the expression and print the result."""
    # 5. Evaluate the program: let x = 5 in let y = x + 3 in x * y
    program = Let("x", Num(5),
                Let("y", Add(Var("x"), Num(3)),
                    Mul(Var("x"), Var("y"))))

    # Initial environment is empty
    initial_env: Env = []

    # Evaluate the expression
    result = eval_expr(program, initial_env)

    # 6. Print the result
    print(result)

if __name__ == "__main__":
    main()

