pure func tree_sum(t: Tree) -> int =
  match t {
    Leaf(v) => v,
    Node(l, v, r) => tree_sum(l) + v + tree_sum(r)
  }

pure func maxInt(a: int, b: int) -> int = if a >= b then a else b

