from enum import Enum

class Color(Enum):
    Red = 0
    Black = 1

class RBTree:
    pass

class Empty(RBTree):
    pass

class Node(RBTree):
    def __init__(self, color, left, value, right):
        self.color = color
        self.left = left
        self.value = value
        self.right = right

def balance(color, left, value, right):
    # Case 1: left-left (left is red with red left child)
    if (color == Color.Black and
        isinstance(left, Node) and left.color == Color.Red and
        isinstance(left.left, Node) and left.left.color == Color.Red):
        return Node(Color.Red,
                    Node(Color.Black, left.left.left, left.left.value, left.left.right),
                    left.value,
                    Node(Color.Black, left.right, value, right))

    # Case 2: left-right (left is red with red right child)
    if (color == Color.Black and
        isinstance(left, Node) and left.color == Color.Red and
        isinstance(left.right, Node) and left.right.color == Color.Red):
        return Node(Color.Red,
                    Node(Color.Black, left.left, left.value, left.right.left),
                    left.right.value,
                    Node(Color.Black, left.right.right, value, right))

    # Case 3: right-left (right is red with red left child)
    if (color == Color.Black and
        isinstance(right, Node) and right.color == Color.Red and
        isinstance(right.left, Node) and right.left.color == Color.Red):
        return Node(Color.Red,
                    Node(Color.Black, left, value, right.left.left),
                    right.left.value,
                    Node(Color.Black, right.left.right, right.value, right.right))

    # Case 4: right-right (right is red with red right child)
    if (color == Color.Black and
        isinstance(right, Node) and right.color == Color.Red and
        isinstance(right.right, Node) and right.right.color == Color.Red):
        return Node(Color.Red,
                    Node(Color.Black, left, value, right.left),
                    right.value,
                    Node(Color.Black, right.right.left, right.right.value, right.right.right))

    # No balancing needed
    return Node(color, left, value, right)

def ins(x, tree):
    if isinstance(tree, Empty):
        return Node(Color.Red, Empty(), x, Empty())

    if x < tree.value:
        return balance(tree.color, ins(x, tree.left), tree.value, tree.right)
    elif x > tree.value:
        return balance(tree.color, tree.left, tree.value, ins(x, tree.right))
    else:
        return tree

def insert(x, tree):
    result = ins(x, tree)
    if isinstance(result, Node):
        return Node(Color.Black, result.left, result.value, result.right)
    return result

def inorder(tree):
    if isinstance(tree, Empty):
        return []
    result = []
    result.extend(inorder(tree.left))
    result.append(tree.value)
    result.extend(inorder(tree.right))
    return result

if __name__ == "__main__":
    tree = Empty()
    values = [7, 3, 18, 10, 22, 8, 11, 26]
    for val in values:
        tree = insert(val, tree)
    print(inorder(tree))

