from typing import Union, final

# 1. Define State and Event types

@final
@dataclass(frozen=True)
class Green:
    timer: int

@final
@dataclass(frozen=True)
class Yellow:
    timer: int

@final
@dataclass(frozen=True)
class Red:
    timer: int

State = Union[Green, Yellow, Red]

@final
@dataclass(frozen=True)
class Tick:
    pass

@final
@dataclass(frozen=True)
class Reset:
    pass

Event = Union[Tick, Reset]

# 3. Implement transition function
def transition(state: State, event: Event) -> State:
    """
    Handles state transitions based on the current state and an event.
    """
    if isinstance(event, Reset):
        return Green(20)

    if isinstance(event, Tick):
        if isinstance(state, Green):
            if state.timer > 1:
                return Green(state.timer - 1)
            else:
                return Yellow(3)
        elif isinstance(state, Yellow):
            if state.timer > 1:
                return Yellow(state.timer - 1)
            else:
                return Red(10)
        elif isinstance(state, Red):
            if state.timer > 1:
                return Red(state.timer - 1)
            else:
                return Green(20)

    # Exhaustiveness check - this should be unreachable
    raise TypeError(f"Unhandled combination of state {type(state).__name__} and event {type(event).__name__}")

# 4. Implement display function
def display(state: State) -> str:
    """
    Formats the state for display.
    """
    if isinstance(state, Green):
        return f"GREEN ({state.timer}sec)"
    elif isinstance(state, Yellow):
        return f"YELLOW ({state.timer}sec)"
    elif isinstance(state, Red):
        return f"RED ({state.timer}sec)"

    # Exhaustiveness check - this should be unreachable
    raise TypeError(f"Unhandled state: {type(state).__name__}")

# 5. Main simulation
def main() -> None:
    """
    Runs the traffic light simulation.
    """
    state: State = Green(20)

    # Apply 25 Tick events
    for _ in range(25):
        state = transition(state, Tick())
        print(display(state))

    # Apply 1 Reset event
    state = transition(state, Reset())
    print(display(state))

    # Apply 5 more Tick events
    for _ in range(5):
        state = transition(state, Tick())
        print(display(state))


if __name__ == "__main__":
    main()

