    Mul(a, b) => {
      let sa = simplify(a);
      let sb = simplify(b);
      match (sa, sb) {
        (Const(0), _) => Const(0),
        (_, Const(0)) => Const(0),
        (Const(1), e2) => e2,
        (e1, Const(1)) => e1,
        (Const(n1), Const(n2)) => Const(n1 * n2),
        _ => Mul(sa, sb)
      }
