from dataclasses import dataclass
from typing import Union

# 1. AST Definition
class Expr:
    pass

@dataclass
class Const(Expr):
    value: int

@dataclass
class Var(Expr):
    name: str

@dataclass
class Add(Expr):
    left: Expr
    right: Expr

@dataclass
class Mul(Expr):
    left: Expr
    right: Expr

# Type alias for clarity
Expression = Union[Const, Var, Add, Mul]

# 5. showExpr
def showExpr(expr: Expression) -> str:
    """Converts an expression AST to a readable string."""
    if isinstance(expr, Const):
        return str(expr.value)
    if isinstance(expr, Var):
        return expr.name
    if isinstance(expr, Add):
        return f"({showExpr(expr.left)} + {showExpr(expr.right)})"
    if isinstance(expr, Mul):
        return f"({showExpr(expr.left)} * {showExpr(expr.right)})"
    # This should be unreachable if types are correct
    raise TypeError(f"Unknown expression type: {type(expr)}")

# 2. diff
def diff(expr: Expression, var: str) -> Expression:
    """Differentiates an expression with respect to a variable."""
    if isinstance(expr, Const):
        return Const(0)
    if isinstance(expr, Var):
        return Const(1) if expr.name == var else Const(0)
    if isinstance(expr, Add):
        # d/dx(f + g) = df/dx + dg/dx
        return Add(diff(expr.left, var), diff(expr.right, var))
    if isinstance(expr, Mul):
        # d/dx(f * g) = f * dg/dx + g * df/dx (product rule)
        f = expr.left
        g = expr.right
        df_dx = diff(f, var)
        dg_dx = diff(g, var)
        return Add(Mul(f, dg_dx), Mul(g, df_dx))
    # This should be unreachable if types are correct
    raise TypeError(f"Unknown expression type: {type(expr)}")

# 3. simplify
def simplify(expr: Expression) -> Expression:
    """Simplifies an expression using algebraic identities."""
    # Recursively simplify children first (post-order traversal)
    if isinstance(expr, Add):
        left = simplify(expr.left)
        right = simplify(expr.right)
        # e + 0 = e
        if isinstance(right, Const) and right.value == 0:
            return left
        # 0 + e = e
        if isinstance(left, Const) and left.value == 0:
            return right
        return Add(left, right)
    if isinstance(expr, Mul):
        left = simplify(expr.left)
        right = simplify(expr.right)
        # e * 0 = 0
        if isinstance(right, Const) and right.value == 0:
            return Const(0)
        # 0 * e = 0
        if isinstance(left, Const) and left.value == 0:
            return Const(0)
        # e * 1 = e
        if isinstance(right, Const) and right.value == 1:
            return left
        # 1 * e = e
        if isinstance(left, Const) and left.value == 1:
            return right
        return Mul(left, right)
    # For Const and Var, no further simplification is possible on the node itself
    return expr

def main():
    """
    Main function to define, differentiate, simplify, and print the expression.
    """
    # 4. Differentiate: x^2 + 3x + 5
    # Represented as: Add(Add(Mul(Var("x"), Var("x")), Mul(Const(3), Var("x"))), Const(5))
    expression = Add(
        Add(
            Mul(Var("x"), Var("x")),
            Mul(Const(3), Var("x"))
        ),
        Const(5)
    )

    # Differentiate the expression with respect to 'x'
    derivative = diff(expression, "x")

    # Simplify the resulting derivative
    simplified_derivative = simplify(derivative)

    # 6. Print the simplified derivative using showExpr
    print(showExpr(simplified_derivative))

if __name__ == "__main__":
    main()

