from dataclasses import dataclass
from typing import Callable, List


@dataclass
class Leaf:
    value: int


@dataclass
class Node:
    left: 'Tree'
    value: int
    right: 'Tree'


Tree = Leaf | Node


def mapTree(fn: Callable[[int], int], tree: Tree) -> Tree:
    """Recursively apply function to all values in the tree."""
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    else:  # Node
        return Node(
            mapTree(fn, tree.left),
            fn(tree.value),
            mapTree(fn, tree.right)
        )


def foldTree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    """In-order fold over tree values."""
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    else:  # Node
        # In-order: left, root, right
        acc = foldTree(fn, acc, tree.left)
        acc = fn(acc, tree.value)
        acc = foldTree(fn, acc, tree.right)
        return acc


def treeToList(tree: Tree) -> List[int]:
    """In-order traversal to list."""
    if isinstance(tree, Leaf):
        return [tree.value]
    else:  # Node
        # In-order: left, root, right
        return treeToList(tree.left) + [tree.value] + treeToList(tree.right)


def treeDepth(tree: Tree) -> int:
    """Calculate the depth of the tree."""
    if isinstance(tree, Leaf):
        return 1
    else:  # Node
        return 1 + max(treeDepth(tree.left), treeDepth(tree.right))


def main():
    # Create the example tree:
    #       4
    #      / \
    #     2   6
    #    / \ / \
    #   1  3 5  7
    tree = Node(
        Node(Leaf(1), 2, Leaf(3)),
        4,
        Node(Leaf(5), 6, Leaf(7))
    )

    # In-order values
    values = treeToList(tree)
    print(values)

    # Doubled values
    doubled_tree = mapTree(lambda x: x * 2, tree)
    doubled_values = treeToList(doubled_tree)
    print(doubled_values)

    # Sum of all values
    total = foldTree(lambda acc, x: acc + x, 0, tree)
    print(total)

    # Tree depth
    depth = treeDepth(tree)
    print(depth)


if __name__ == "__main__":
    main()

