    s :: rest => if s.var == name then Some(s.typ) else lookupSub(name, rest)
  }

pure func apply(subst: [Sub], typ: Type) -> Type =
  match typ {
    TVar(n) => match lookupSub(n, subst) { Some(t) => t, None => typ },
    TInt => TInt,
    TBool => TBool,
    TFunc(a, r) => TFunc(apply(subst, a), apply(subst, r))
  }

pure func unify(t1: Type, t2: Type) -> Option[[Sub]] =
  match t1 {
    TInt => match t2 { TInt => Some([]), _ => None },
    TBool => match t2 { TBool => Some([]), _ => None },
    TVar(n1) => Some([{var: n1, typ: t2}]),
    TFunc(a1, r1) =>
      match t2 {
        TFunc(a2, r2) =>
          match unify(a1, a2) {
            Some(s1) =>
              match unify(r1, r2) {
                Some(s2) => Some(concat(s1, s2)),
                None => None
              },
            None => None
          },
        _ => None
      },
    _ => match t2 { TVar(n2) => Some([{var: n2, typ: t1}]), _ => None }
  }

pure func showType(t: Type) -> string =
  match t {
    TInt => "TInt",
    TBool => "TBool",
    TVar(n) => "TVar(" ++ n ++ ")",
    TFunc(a, r) => "TFunc(" ++ showType(a) ++ " -> " ++ showType(r) ++ ")"
  }

pure func getVar(name: string, subst: [Sub]) -> Type =
  match lookupSub(name, subst) {
    Some(t) => t,
    None => TVar(name)
  }

export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  match unify(t1, t2) {
    Some(subst) => {
      let sa = showType(getVar("a", subst));
      let sb = showType(getVar("b", subst));
      println("a = " ++ sa);
      println("b = " ++ sb)
    },
    None => println("Unification failed")
  }
}

